import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

layernorm_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
__global__ void layer_norm_reduce_kernel(const float* __restrict__ x,
                                          double* __restrict__ sum_arr,
                                          double* __restrict__ sumsq_arr,
                                          int N, int D, int blocks_per_row) {
    int row = blockIdx.x / blocks_per_row;
    int chunk = blockIdx.x % blocks_per_row;
    if (row >= N) return;
    const float* x_n = x + (size_t)row * D;
    int D4 = D / 4;
    const float4* x4 = reinterpret_cast<const float4*>(x_n);
    double sum = 0.0;
    double sumsq = 0.0;
    for (int i = chunk * blockDim.x + threadIdx.x; i < D4; i += blocks_per_row * blockDim.x) {
        float4 v = __ldg(&x4[i]);
        sum += (double)v.x + (double)v.y + (double)v.z + (double)v.w;
        sumsq += (double)v.x * (double)v.x + (double)v.y * (double)v.y +
                 (double)v.z * (double)v.z + (double)v.w * (double)v.w;
    }
    for (int i = D4 * 4 + chunk * blockDim.x + threadIdx.x; i < D; i += blocks_per_row * blockDim.x) {
        float v = __ldg(&x_n[i]);
        sum += (double)v;
        sumsq += (double)v * (double)v;
    }
    // warp-level reduction using shuffle instructions to avoid full shared-memory tree reduction
    unsigned mask = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset);
        sumsq += __shfl_down_sync(mask, sumsq, offset);
    }
    extern __shared__ double sdata[];
    int numWarps = blockDim.x / 32;
    double* s_sum = sdata;
    double* s_sumsq = sdata + numWarps;
    int lane = threadIdx.x & 31;
    int warpId = threadIdx.x >> 5;
    if (lane == 0) {
        s_sum[warpId] = sum;
        s_sumsq[warpId] = sumsq;
    }
    __syncthreads();
    if (threadIdx.x < numWarps) {
        double wsum = s_sum[threadIdx.x];
        double wsumsq = s_sumsq[threadIdx.x];
        for (int offset = numWarps / 2; offset > 0; offset >>= 1) {
            wsum += __shfl_down_sync(mask, wsum, offset, numWarps);
            wsumsq += __shfl_down_sync(mask, wsumsq, offset, numWarps);
        }
        if (threadIdx.x == 0) {
            atomicAdd(&sum_arr[row], wsum);
            atomicAdd(&sumsq_arr[row], wsumsq);
        }
    }
}
__global__ void layer_norm_finalize_kernel(const double* __restrict__ sum_arr,
                                            const double* __restrict__ sumsq_arr,
                                            double* __restrict__ mean_arr,
                                            float* __restrict__ invstd_arr,
                                            int N, int D, float eps) {
    int n = blockIdx.x * blockDim.x + threadIdx.x;
    if (n < N) {
        double mean = sum_arr[n] / D;
        double var = sumsq_arr[n] / D - mean * mean;
        mean_arr[n] = mean;
        invstd_arr[n] = rsqrtf((float)var + eps);
    }
}
__global__ void layer_norm_normalize_kernel(const float* __restrict__ x,
                                             const float* __restrict__ gamma,
                                             const float* __restrict__ beta,
                                             float* __restrict__ out,
                                             const double* __restrict__ mean_arr,
                                             const float* __restrict__ invstd_arr,
                                             int N, int D, int blocks_per_row) {
    int row = blockIdx.x / blocks_per_row;
    int chunk = blockIdx.x % blocks_per_row;
    if (row >= N) return;
    const float* x_n = x + (size_t)row * D;
    float* out_n = out + (size_t)row * D;
    double mean_l = mean_arr[row];
    float invstd_l = invstd_arr[row];
    int D4 = D / 4;
    const float4* x4 = reinterpret_cast<const float4*>(x_n);
    const float4* gamma4 = reinterpret_cast<const float4*>(gamma);
    const float4* beta4 = reinterpret_cast<const float4*>(beta);
    float4* out4 = reinterpret_cast<float4*>(out_n);
    for (int i = chunk * blockDim.x + threadIdx.x; i < D4; i += blocks_per_row * blockDim.x) {
        float4 v = __ldg(&x4[i]);
        float4 g = __ldg(&gamma4[i]);
        float4 b = __ldg(&beta4[i]);
        float4 o;
        o.x = (float)((double)v.x - mean_l) * invstd_l * g.x + b.x;
        o.y = (float)((double)v.y - mean_l) * invstd_l * g.y + b.y;
        o.z = (float)((double)v.z - mean_l) * invstd_l * g.z + b.z;
        o.w = (float)((double)v.w - mean_l) * invstd_l * g.w + b.w;
        out4[i] = o;
    }
    for (int i = D4 * 4 + chunk * blockDim.x + threadIdx.x; i < D; i += blocks_per_row * blockDim.x) {
        float v = __ldg(&x_n[i]);
        out_n[i] = (float)((double)v - mean_l) * invstd_l * __ldg(&gamma[i]) + __ldg(&beta[i]);
    }
}
torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps) {
    auto x_contig = x.contiguous();
    auto out = torch::empty_like(x_contig);
    int64_t D = gamma.numel();
    int64_t N = x_contig.numel() / D;
    int threads = 256;
    int64_t D4_count = D / 4;
    int blocks_per_row = (int)((D4_count + threads - 1) / threads);
    if (blocks_per_row < 1) blocks_per_row = 1;
    if (blocks_per_row > 64) blocks_per_row = 64;
    auto options_double = torch::TensorOptions().dtype(torch::kFloat64).device(x_contig.device());
    auto options_float = torch::TensorOptions().dtype(torch::kFloat32).device(x_contig.device());
    auto sum_arr = torch::zeros({N}, options_double);
    auto sumsq_arr = torch::zeros({N}, options_double);
    auto mean_arr = torch::empty({N}, options_double);
    auto invstd_arr = torch::empty({N}, options_float);
    size_t shared_mem = 2 * threads * sizeof(double);
    int reduce_blocks = (int)N * blocks_per_row;
    layer_norm_reduce_kernel<<<reduce_blocks, threads, shared_mem>>>(
        x_contig.data_ptr<float>(),
        sum_arr.data_ptr<double>(),
        sumsq_arr.data_ptr<double>(),
        (int)N, (int)D, blocks_per_row
    );
    int finalize_threads = 256;
    int finalize_blocks = (int)((N + finalize_threads - 1) / finalize_threads);
    layer_norm_finalize_kernel<<<finalize_blocks, finalize_threads>>>(
        sum_arr.data_ptr<double>(),
        sumsq_arr.data_ptr<double>(),
        mean_arr.data_ptr<double>(),
        invstd_arr.data_ptr<float>(),
        (int)N, (int)D, (float)eps
    );
    layer_norm_normalize_kernel<<<reduce_blocks, threads>>>(
        x_contig.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        mean_arr.data_ptr<double>(),
        invstd_arr.data_ptr<float>(),
        (int)N, (int)D, blocks_per_row
    );
    return out;
}
"""

layernorm_cpp_source = r"""
torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps);
"""

layernorm_module = load_inline(
    name="layernorm_module",
    cpp_sources=layernorm_cpp_source,
    cuda_sources=layernorm_source,
    functions=["layer_norm_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Layer Normalization using a custom CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5
        self.layernorm_module = layernorm_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.layernorm_module.layer_norm_cuda(x, self.weight, self.bias, self.eps)


batch_size = 16
features = 64
dim1 = 256
dim2 = 256


def get_inputs():
    x = torch.randn(batch_size, features, dim1, dim2)
    mean = 1000
    std_dev = 0.1
    x = x * std_dev + mean
    return [x.cuda()]


